var isReady = false;
function __Model() {
	this.bindMap = {};
	this.tmpCnt = 0
}
__Model.prototype.bind = function(elem) {
	var id = elem.getAttribute("id");
	var name = elem.getAttribute("name");
	var ref = elem.getAttribute("ref");
	var format = elem.getAttribute("format");
	var jsonObj = null;
	var __this = this;
	if (typeof (id) == "undefined" || id == null || id == "") {
		elem.setAttribute("id", "__binding_" + elem.getAttribute("name")
				+ (this.tmpCnt));
		id = "__binding_" + elem.getAttribute("name") + (this.tmpCnt);
		this.tmpCnt++
	}
	if (typeof (ref) != "undefined" && ref != null && ref != "") {
		try {
			jsonObj = eval(this.getJsonPath(ref))
		} catch (e) {
			this.makeJsonObj(ref)
		}
		if (typeof (jsonObj) == "undefined") {
			this.makeJsonObj(ref)
		}
		if (elem.type === "select-one") {
			$("#" + id).change(function() {
				__this.setValue(ref, $(this).val())
			})
		} else {
			if (elem.type === "text" || elem.type === "password") {
				$("#" + id).change(function(e) {
					var _val = $(this).val();
					_val = __this.eraseFormat(elem, _val);
					__this.setValue(ref, _val)
				})
			} else {
				if (elem.type === "textarea") {
					$("#" + id).change(function() {
						__this.setValue(ref, $(this).val())
					})
				} else {
					if (elem.nodeName.toLowerCase() === "td"
							|| elem.nodeName.toLowerCase() === "span") {
						$("#" + id).change(function() {
							var _val = $(this).text();
							_val = __this.eraseFormat(elem, _val);
							__this.setValue(ref, _val)
						})
					} else {
						if (elem.nodeName.toLowerCase() === "div") {
							$("#" + id).change(
									function(e) {
										var _checkName = e.target
												.getAttribute("name");
										var _val = "";
										$(
												"input[name='" + _checkName
														+ "']:checked").each(
												function(i) {
													if (i > 0) {
														_val += ","
													}
													_val += $(this).val()
												});
										__this.setValue(ref, _val);
										$(this).val(_val)
									})
						}
					}
				}
			}
		}
	} else {
		ref = ""
	}
	return ref
};
