__Model.prototype.getJsonPath = function(ref) {
	if (ref.substring(0, 1) == "/") {
		ref = ref.substring(1, ref.length)
	}
	ref = ref.replace(/\//ig, ".");
	var tokens = ref.split(".");
	var jsonPath = "";
	var ret = null;
	for ( var i = 0; i < tokens.length; i++) {
		jsonPath += (i == 0) ? tokens[i] : "." + tokens[i] + "";
		try {
			if (i < tokens.length - 1) {
				if (eval(jsonPath + ".constructor") == Array) {
					if (tokens[i].indexOf("[") < 0) {
						jsonPath += "[0]"
					}
				}
			}
		} catch (e) {
		}
	}
	return jsonPath
};
__Model.prototype.makeJsonObj = function(ref) {
	if (ref.substring(0, 1) == "/") {
		ref = ref.substring(1, ref.length)
	}
	ref = ref.replace(/\//ig, ".");
	var tokens = ref.split(".");
	var jsonPath = "";
	var cur_jsonPath = "";
	var ret = null;
	var arrayReg = /\[([0-9]*)\]/;
	for ( var i = 0; i < tokens.length; i++) {
		cur_jsonPath = (i == 0) ? tokens[i] : jsonPath + "."
				+ tokens[i].replace(arrayReg, "") + "";
		if (typeof (eval(cur_jsonPath)) == "undefined") {
			var _o = eval(jsonPath);
			if (_o == "") {
				_o = {}
			}
			if (tokens[i].indexOf("[") > -1) {
				_o[tokens[i].replace(arrayReg, "")] = []
			} else {
				_o[tokens[i].replace(arrayReg, "")] = {}
			}
			eval(jsonPath + " = _o")
		}
		if (arrayReg.test(tokens[i])) {
			arrayReg.exec(tokens[i]);
			var _inx = RegExp.$1;
			for ( var j = 0; j <= _inx; j++) {
				if (typeof (eval(jsonPath + "." + tokens[i])) == "undefined"
						|| eval(jsonPath + "."
								+ tokens[i].replace(arrayReg, "")
								+ ".constructor") != Array) {
					if (typeof (eval(jsonPath + "."
							+ tokens[i].replace(arrayReg, "") + "[" + j + "]")) == "undefined"
							|| eval(jsonPath + "."
									+ tokens[i].replace(arrayReg, "")
									+ ".constructor") != Array) {
						if (j == 0) {
							eval(jsonPath + "."
									+ tokens[i].replace(arrayReg, "")
									+ " = [];")
						}
						eval(jsonPath + "." + tokens[i].replace(arrayReg, ""))
								.push("")
					}
				}
			}
		}
		jsonPath += (i > 0) ? "." + tokens[i] : tokens[i]
	}
};
__Model.prototype.getJsonKeys = function(c) {
	var b = new Array();
	for ( var a in c) {
		b[b.length] = a
	}
	return b
};
