__Model.prototype.util.executeFormat = function(d, l) {
	var j = "";
	var k = "";
	try {
		k = d.getAttribute("format")
	} catch (h) {
	}
	if (k == null || typeof k == "undefined" || k == "undefined") {
		k = ""
	}
	if (k.indexOf(".") < 0 && (k.indexOf("9") > -1 || k.indexOf("#") > -1)) {
		l = l.replace(/[^0-9\.]/ig, "")
	} else {
		l = l
	}
	if (k.indexOf("9") > -1) {
		d.setAttribute("maxlength", k.length.toString());
		var a = "";
		var b = "";
		var c = 0;
		if ($(d).val() != "") {
			for ( var g = 0; g < l.length + 1; g++) {
				a = k.substring(g, g + 1);
				if (a == "-") {
					b += "-";
					c++
				} else {
					b += l.substring(g - c, g + 1 - c)
				}
			}
		}
		if (b != "") {
			j = b
		} else {
			j = l
		}
	} else {
		if (k.indexOf("#") > -1) {
			var b = "";
			if (k.indexOf(",") > -1) {
				var f = 1;
				for ( var g = l.length; g > 0; g--) {
					if (f == 3 && g > 1) {
						b = "," + l.substring(g - 1, g) + b;
						f = 1
					} else {
						b = l.substring(g - 1, g) + b;
						f++
					}
				}
			} else if (k.indexOf(".") > -1) {
				var f = k.split(".");
				b = parseFloat(l).toFixed(f[1].length);				
			} else {
				b = l
			}
			if (b != "") {
				j = b
			} else {
				j = l
			}
		} else if (k == "yyyy-mm") {
			if(l.length >= 6) {
				j = l.substring(0,4) + "-" + l.substring(4, 6)
			}else {
				j = l
			}			
		} else if (k == "yyyy-mm-dd") {
			if(l.length >= 8) {
				j = l.substring(0,4) + "-" + l.substring(4, 6) + "-" + l.substring(6, 8)
			}else {
				j = l
			}
		} else if (k == "yyyy/mm/dd") {
			if(l.length >= 8) {
				j = l.substring(0,4) + "/" + l.substring(4, 6) + "/" + l.substring(6, 8)
			}else {
				j = l
			}
		} else {
			j = l
		}
	}
	return j
};
